package com.vitalminds.controller;
import com.vitalminds.model.*; import com.vitalminds.repository.*; import com.vitalminds.service.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Controller; import org.springframework.web.bind.annotation.*; import java.time.*; import java.nio.charset.StandardCharsets; import java.util.*;
@Controller public class V6Controller {
 private final UserService users; private final HealthRecordRepository records; private final AIHealthService ai; private final ActivityLogRepository activity; private final SleepLogRepository sleep; private final AppointmentRepository appointments;
 public V6Controller(UserService u,HealthRecordRepository r,AIHealthService ai,ActivityLogRepository a,SleepLogRepository s,AppointmentRepository ap){users=u;records=r;this.ai=ai;activity=a;sleep=s;appointments=ap;}
 private User user(Authentication a){return users.findByEmail(a.getName()).orElseThrow();}
 @PostMapping("/api/assistant") @ResponseBody public Map<String,String> assistant(Authentication a,@RequestParam String question){User u=user(a);var rs=records.findTop20ByUserIdOrderByUploadedAtDesc(u.getId());return Map.of("answer",ai.answer(u,rs.isEmpty()?null:rs.get(0),question,activity.findTop14ByUserIdOrderByDateDesc(u.getId()),sleep.findTop14ByUserIdOrderByDateDesc(u.getId())));}
 @GetMapping("/api/report/explain") @ResponseBody public Map<String,String> explain(Authentication a){User u=user(a);var rs=records.findTop20ByUserIdOrderByUploadedAtDesc(u.getId());return Map.of("answer",ai.explain(u,rs.isEmpty()?null:rs.get(0)));}
 @PostMapping("/api/activity") public String activity(Authentication a,@RequestParam String date,@RequestParam(required=false) Integer steps,@RequestParam(required=false) Integer minutes,@RequestParam(required=false,defaultValue="Walking") String activityType){ActivityLog x=new ActivityLog();x.setUser(user(a));x.setDate(LocalDate.parse(date));x.setSteps(steps);x.setMinutes(minutes);x.setActivityType(activityType);activity.save(x);return "redirect:/dashboard?v6Saved";}
 @PostMapping("/api/sleep") public String sleep(Authentication a,@RequestParam String date,@RequestParam Double hours,@RequestParam(required=false,defaultValue="Average") String quality){SleepLog x=new SleepLog();x.setUser(user(a));x.setDate(LocalDate.parse(date));x.setHours(hours);x.setQuality(quality);sleep.save(x);return "redirect:/dashboard?v6Saved";}
 @PostMapping("/api/appointments") public String appointment(Authentication a,@RequestParam String doctorName,@RequestParam(required=false) String specialty,@RequestParam String appointmentAt,@RequestParam(required=false) String notes){Appointment x=new Appointment();x.setUser(user(a));x.setDoctorName(doctorName);x.setSpecialty(specialty);x.setAppointmentAt(LocalDateTime.parse(appointmentAt));x.setNotes(notes);appointments.save(x);return "redirect:/dashboard?v6Saved";}
 @PostMapping("/api/nutrition") @ResponseBody public Map<String,Object> nutrition(Authentication a,@RequestParam Double weightKg,@RequestParam Double heightCm,@RequestParam Integer age,@RequestParam String gender,@RequestParam String activityLevel){double bmr=gender.equalsIgnoreCase("male")?(10*weightKg+6.25*heightCm-5*age+5):(10*weightKg+6.25*heightCm-5*age-161);double mult=switch(activityLevel){case "Light"->1.375;case "Moderate"->1.55;case "High"->1.725;default->1.2;};return Map.of("bmr",Math.round(bmr),"maintenanceCalories",Math.round(bmr*mult),"note","Estimate only; calorie needs vary with health conditions, body composition and goals.");}
 @GetMapping("/api/v6-data") @ResponseBody public Map<String,Object> data(Authentication a){User u=user(a);return Map.of("activity",activity.findTop14ByUserIdOrderByDateDesc(u.getId()),"sleep",sleep.findTop14ByUserIdOrderByDateDesc(u.getId()),"appointments",appointments.findTop6ByUserIdOrderByAppointmentAtAsc(u.getId()));}
 @GetMapping("/api/export-v6") public ResponseEntity<byte[]> export(Authentication a){User u=user(a);var rs=records.findTop20ByUserIdOrderByUploadedAtDesc(u.getId());StringBuilder s=new StringBuilder("Date,File,Hemoglobin,Glucose,Cholesterol,Systolic,Diastolic,BMI,Summary\n");for(var r:rs)s.append(q(r.getUploadedAt()==null?"":r.getUploadedAt().toString())).append(',').append(q(r.getFileName())).append(',').append(v(r.getHemoglobin())).append(',').append(v(r.getGlucose())).append(',').append(v(r.getCholesterol())).append(',').append(v(r.getSystolic())).append(',').append(v(r.getDiastolic())).append(',').append(v(r.getBmi())).append(',').append(q(r.getSummary())).append('\n');return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=VitalMinds-V6-health-data.csv").contentType(MediaType.parseMediaType("text/csv")).body(s.toString().getBytes(StandardCharsets.UTF_8));}
 private String v(Object o){return o==null?"":o.toString();} private String q(String s){return "\""+(s==null?"":s.replace("\"","\"\""))+"\"";}
}
